+            boolean isQueueEmpty = queue.isEmpty();
+
+            if (isDone) {
+                Throwable e = error;
+                if (e != null) {
+                    throw new RuntimeException(e);
+                } else if (isQueueEmpty) {
+                    return false;
+                }
+            }
