+        // thread, but to avoid potential deadlocks
+        // we just try to release a possibly blocked
+        // consumer
+        signalConsumer();
+    }
+
+    @Override
+    public void onError(Throwable t) {
+        clearQueue();
+        error = t;
+        done = true;
+        signalConsumer();
+    }
+
+    @Override
+    public void onComplete() {
